        // Simple AND logic gate (linearly separable)
        const inputs = [
            [0, 0],
            [0, 1],
            [1, 0],
            [1, 1]
        ];
        const outputs = [
            -1, // 0 AND 0 => 0 (represented as -1)
            -1, // 0 AND 1 => 0
            -1, // 1 AND 0 => 0
            1   // 1 AND 1 => 1
        ];

