        const k = 3;

        // Run ckmeans
        const result = simple_statistics.ckmeans(data, k);

        // 1️⃣  Verify we got the requested number of clusters
        assert.strictEqual(
            result.length,
            k,
            `ckmeans should return exactly ${k} clusters`
        );

