        const zeroData = [0, 0, 0, 0];
        const zeroResult = simple_statistics.coefficientOfVariation(zeroData);
        assert.ok(isNaN(zeroResult), `Expected NaN for zero data, got ${zeroResult}`);

        done();
    });
