        // err = (0-0)^2 + (2-0)^2 + (4-0)^2 = 0 + 4 + 16 = 20
        // r² = 1 - err / sumOfSquares = 1 - 20/8 = -1.5
        assert.strictEqual(r3, -1.5, 'rSquared should be -1.5 for the given bad fit');

        done();
