    function mannWhitneyU(x, y) {
        const nX = x.length;
        // simple_statistics.wilcoxonRankSum returns the sum of the ranks of the first sample (x)
        const sumRanksX = simple_statistics.wilcoxonRankSum(x, y);
        // U = sumRanksX - nX*(nX+1)/2
